+import { useState } from "react";
+import { useUploadBOQ } from "@/hooks/useBoqs";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Label } from "@/components/ui/label";
+import { Textarea } from "@/components/ui/textarea";
+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+
+interface BOQUploadProps {
+  projectId: string;
+}
+
+export function BOQUpload({ projectId }: BOQUploadProps) {
+  const [file, setFile] = useState<File | null>(null);
+  const [notes, setNotes] = useState("");
+  const uploadMutation = useUploadBOQ();
+
+  const handleSubmit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    if (!file) return;
+    await uploadMutation.mutateAsync({ projectId, file, notes });
+    setFile(null);
+    setNotes("");
+  };
+
+  return (
+    <Card>
+      <CardHeader>
+        <CardTitle>Upload BOQ</CardTitle>
+      </CardHeader>
+      <CardContent>
+        <form onSubmit={handleSubmit} className="space-y-4">
+          <div className="space-y-2">
+            <Label htmlFor="boq-file">BOQ File (.xlsx, .json)</Label>
+            <Input
+              id="boq-file"
+              type="file"
+              accept=".xlsx,.json"
+              onChange={(e) => setFile(e.target.files?.[0] ?? null)}
+            />
+          </div>
+          <div className="space-y-2">
+            <Label htmlFor="boq-notes">Notes (optional)</Label>
+            <Textarea
+              id="boq-notes"
+              value={notes}
+              onChange={(e) => setNotes(e.target.value)}
+              placeholder="Add notes about this BOQ version..."
+            />
+          </div>
+          <Button type="submit" disabled={!file || uploadMutation.isPending}>
+            {uploadMutation.isPending ? "Uploading..." : "Upload BOQ"}
+          </Button>
+          {uploadMutation.isError && (
+            <p className="text-sm text-red-500">Upload failed. Please try again.</p>
+          )}
+        </form>
+      </CardContent>
+    </Card>
+  );
+}
